draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw a bird
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + Math.sin(t)*50, H/2, 20, 0, 2*Math.PI);
  ctx.fill();
  ctx.stroke();

  // Draw wings
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 - Math.cos(t)*30, H/2 + 50);
  ctx.lineTo(W/2 + Math.sin(t)*50 + Math.cos(t)*30, H/2 + 50);
  ctx.closePath();
  ctx.stroke();

  // Draw legs
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 - 10, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 + Math.sin(t)*50, H/2 + 20);
  ctx.lineTo(W/2 + Math.sin(t)*50 + 10, H/2 + 50);
  ctx.stroke();

  ctx.restore();
}
